".ha-pays .mp{background:#00B1EA;color:#fff;border-color:#00B1EA}.ha-pays .vi{background:#1A1F71;color:#fff;border-color:#1A1F71;font-style:italic}.ha-pays .am{background:#2E77BC;color:#fff;border-color:#2E77BC}.ha-pays .na{background:#FF6A00;color:#fff;border-color:#FF6A00}",
