/* escritorio */
"@media(min-width:750px){",
" .ha-sec{padding:72px 0}",
" .ha-hero{padding:40px 0 48px}.ha-hero .ha-wrap{grid-template-columns:1fr 1fr;gap:48px;align-items:center}",
