" .ha-hero h1{font-size:38px}.ha-hero p.lead{font-size:16px}.ha-hero .ha-btn{max-width:460px}.ha-choice{text-align:left;max-width:460px}.ha-choice p{justify-content:flex-start}",
" .ha-seals .g{grid-template-columns:repeat(3,1fr)}",
" .ha-revs .ha-h2{font-size:36px}.ha-rv-card{flex-basis:50%;padding:0 8px}.ha-rprev{display:block}",
" .ha-strip img{width:150px;height:150px}",
" .ha-sci h2.tw{font-size:32px;text-align:center;min-height:auto}.ha-sci .intro{text-align:center;font-size:16px;max-width:720px;margin:14px auto 30px}",
" .ha-cards{grid-template-columns:repeat(4,1fr)}",
