" .ha-num .ha-h2{font-size:31px;max-width:620px}.ha-stats{max-width:720px;margin:44px auto 0}",
" .ha-cmp .g{max-width:560px}.ha-cmp .us li,.ha-cmp .ot li{font-size:15px}",
" .ha-buy .g{grid-template-columns:1fr 1fr;gap:48px;align-items:start}.ha-gal{position:sticky;top:90px}",
