/* ─────────────────────────────────────────────────────────────────────
   6 · INTERACCIONES
   ───────────────────────────────────────────────────────────────────── */
function slider(track, dots, prev, next) {
  var items = track.children;
  function per() { return Math.max(1, Math.round(track.clientWidth / items[0].getBoundingClientRect().width)); }
  function pages() { return Math.max(1, items.length - per() + 1); }
  function cur() { return Math.round(track.scrollLeft / items[0].getBoundingClientRect().width); }
  function go(i) { var n = pages(); i = (i + n) % n; track.scrollLeft = i * items[0].getBoundingClientRect().width; }
  function draw() { var n = pages(), c = Math.min(cur(), n - 1), h = ""; for (var i = 0; i < n; i++) h += '<b data-d="' + i + '"' + (i === c ? ' class="on"' : "") + "></b>"; dots.innerHTML = h; }
  if (prev) prev.addEventListener("click", function () { go(cur() - 1); });
  if (next) next.addEventListener("click", function () { go(cur() + 1); });
  dots.addEventListener("click", function (e) { var d = e.target.getAttribute("data-d"); if (d !== null) go(+d); });
  var t; track.addEventListener("scroll", function () { clearTimeout(t); t = setTimeout(draw, 80); }, { passive: true });
  window.addEventListener("resize", draw); draw();
}
function interact(root) {
  var spans = root.querySelectorAll("#ha-ann span"), a = 0;
  if (spans.length > 1) setInterval(function () { spans[a].classList.remove("on"); a = (a + 1) % spans.length; spans[a].classList.add("on"); }, 3500);
  var b = root.querySelector("#ha-burger"), dr = root.querySelector("#ha-drawer");
  if (b) b.addEventListener("click", function () { dr.classList.toggle("open"); });
  var rc = root.querySelector("[data-rcar]");
  if (rc) slider(rc.querySelector(".ha-rtrack"), rc.querySelector(".ha-dots"), rc.querySelector("[data-rp]"), rc.querySelector("[data-rn]"));
  var ft = root.querySelector(".ha-ftrack");
  if (ft) slider(ft, root.querySelector(".ha-fnav .ha-dots"), root.querySelector("[data-fp]"), root.querySelector("[data-fn]"));
  /* galería */
  var main = root.querySelector("#ha-main img"), th = root.querySelectorAll(".ha-thumbs button"), gi = 0, G = HOME.fotos.galeria;
  function show(i) {
    gi = (i + G.length) % G.length; main.style.opacity = 0;
    setTimeout(function () { main.src = G[gi]; main.style.opacity = 1; }, 160);
    th.forEach(function (x, k) { x.classList.toggle("on", k === gi); });
    var t = th[gi], w = t.parentNode; w.scrollLeft = t.offsetLeft - w.offsetLeft - (w.clientWidth - t.clientWidth) / 2;
  }
  th.forEach(function (x) { x.addEventListener("click", function () { show(+x.getAttribute("data-i")); }); });
  var gp = root.querySelector("[data-gp]"), gn = root.querySelector("[data-gn]");
  if (gp) gp.addEventListener("click", function () { show(gi - 1); });
  if (gn) gn.addEventListener("click", function () { show(gi + 1); });
  /* acordeón: uno abierto a la vez */
  var ds = root.querySelectorAll(".ha-acc details");
  ds.forEach(function (d) { d.addEventListener("toggle", function () { if (d.open) ds.forEach(function (o) { if (o !== d) o.open = false; }); }); });
  /* newsletter en vista previa */
  var nf = root.querySelector("#ha-news");
  if (nf && window.HOME_ATLAS_PREVIEW) nf.addEventListener("submit", function (e) { e.preventDefault(); nf.outerHTML = '<p style="margin-top:22px"><b>¡Gracias! Ya estás suscripto.</b></p>'; });
  /* título que se escribe solo */
  function type(h) {
    var txt = h.getAttribute("data-tw"), out = h.querySelector(".tx"), i = 0;
    (function step() { out.textContent = txt.slice(0, i); if (i++ < txt.length) setTimeout(step, 55); })();
  }
  /* aparición + contadores + barras */
  function count(el) {
    var end = +el.getAttribute("data-count"), t0 = null;
    function f(ts) { if (!t0) t0 = ts; var p = Math.min((ts - t0) / 1400, 1); el.textContent = Math.round(end * (1 - Math.pow(1 - p, 3))); if (p < 1) requestAnimationFrame(f); }
    requestAnimationFrame(f);
  }
  function reveal(el) {
    el.classList.add("in");
    el.querySelectorAll("[data-count]").forEach(count);
    el.querySelectorAll("[data-w]").forEach(function (b) { b.style.width = b.getAttribute("data-w") + "%"; });
    el.querySelectorAll("[data-tw]").forEach(type);
  }
  var els = root.querySelectorAll(".ha-up");
  if (!("IntersectionObserver" in window)) { els.forEach(reveal); return; }
  var io = new IntersectionObserver(function (en) {
    en.forEach(function (e) { if (e.isIntersecting) { reveal(e.target); io.unobserve(e.target); } });
  }, { threshold: .12 });
  els.forEach(function (e) { io.observe(e); });
}

